const sensorGroups={1:[{name:"Temp & Humidity Sensor B",img:"../picture/sensor_temp_b.jpg",deviceId:"8266_2"},{name:"Dust Sensor",img:"../picture/sensor_dust.jpg",deviceId:"8266_3"},{name:"Air Quality Sensor",img:"../picture/sensor_air.jpg",deviceId:"8266_3"}],2:[{name:"Temp & Humidity Sensor A",img:"../picture/sensor_temp_a.jpg",deviceId:"8266_4"},{name:"Power Sensor",img:"../picture/sensor_power.jpg",deviceId:"8266_5"}]};async function checkSensorStatus(e){try{const s=await fetch("http://192.168.3.85:9090/allData/allSenosrData");if(!s.ok)return!1;const n=await s.json();for(const s in n){const t=n[s];if(Array.isArray(t)){if(t.find(s=>s.deviceId===e))return!0}}return!1}catch(e){return console.error("Failed to retrieve sensor API data:",e),!1}}async function showGroup(e){const s=document.getElementById("layout-container"),n=document.getElementById("sensor-details"),t=sensorGroups[e];if(!n||!t)return;s&&s.classList.remove("is-centered"),n.innerHTML='<div style="font-size:20px; font-weight:bold; color:#666;">Loading sensor status...</div>';const r=await Promise.all(t.map(async e=>{const s=await checkSensorStatus(e.deviceId),n=s?"Status: Active":"Status: Inactive",t=s?"color: #2e7d32;":"color: #d32f2f;";return`\n                <div class="sensor-card">\n                    <img src="${e.img}" alt="${e.name}" onerror="this.src='../picture/sensorplace.png'">\n                    <h3>${e.name}</h3>\n                    <p class="status" style="${t}">${n}</p>\n                </div>\n            `}));n.innerHTML=`<div class="card-list">${r.join("")}</div>`}